const form = document.querySelector("form");

form.addEventListener("submit", async (event) => {
  event.preventDefault();
  const res = await fetch(form.action, { method: "POST", body: new FormData(form) });
  form.insertAdjacentHTML("afterend", res.ok ? "<p>Thanks, got it.</p>" : "<p>Something went wrong. Please try again.</p>");
});

:root {
  --surface: #0f131b;
  --text: #f5f7fb;
  --muted: #b3bccd;
  --space: 1rem;
  --radius: 12px;
}

.card {
  padding: calc(var(--space) * 1.5);
  border-radius: var(--radius);
  background: var(--surface);
  color: var(--text);
}

const queue = JSON.parse(localStorage.getItem("queue") ?? "[]");

export function save(note) {
  queue.push({ id: crypto.randomUUID(), note, at: Date.now() });
  localStorage.setItem("queue", JSON.stringify(queue));
  flush();
}

async function flush() {
  while (queue.length && navigator.onLine) {
    const item = queue[0];
    const res = await fetch("/api/notes", { method: "POST", body: JSON.stringify(item) });
    if (!res.ok) return;
    queue.shift();
    localStorage.setItem("queue", JSON.stringify(queue));
  }
}
